const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.text}"/></svg>`;
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():'idea-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);const now=Date.now();const covers={room:'https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?w=750&auto=format&fit=crop&q=80',hardware:'https://images.unsplash.com/photo-1504148455328-c376907d081c?w=750&auto=format&fit=crop&q=80',desk:'https://images.unsplash.com/photo-1497215728101-856f4ea42174?w=500&auto=format&fit=crop&q=80',travel:'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?w=500&auto=format&fit=crop&q=80',food:'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?w=500&auto=format&fit=crop&q=80'};
const seed=[{id:'quotation',title:'Interior quotation builder',notes:'A simple tool to help interior designers create clear, accurate quotations for clients.\n\n• Select rooms, materials and measurements\n• Calculate material and labour costs\n• Export a professional quotation',category:'Business',stage:'Exploring',why:'Help homeowners understand their renovation budget before work begins.',trigger:'Creating quotations manually takes time. A simpler workflow could help.',next:'Ask 3 homeowners for feedback',cover:covers.room,reminder:new Date(now+3600000).toISOString(),links:['interior','pricing']},{id:'hardware',title:'Hardware shop',notes:'A neighbourhood hardware shop with an online catalogue and local delivery. Start with paint, wall putty and everyday essentials.',category:'Business',stage:'Captured',cover:covers.hardware,reminder:new Date(now+7200000).toISOString(),links:['interior']},{id:'routine',title:'Morning routine app',notes:'A minimal app to design and track personal morning rituals.',category:'Personal',stage:'Captured',cover:covers.desk},{id:'travel',title:'Camper van road trips',notes:'Plan and document scenic road trips. Collect places worth returning to.',category:'Personal',stage:'Trying',cover:covers.travel},{id:'meal',title:'Healthy meal prep service',notes:'A subscription service for fresh, nutritious, ready-to-cook meals.',category:'Business',stage:'Exploring',cover:covers.food},{id:'interior',title:'Interior business',notes:'Build a thoughtful end-to-end interior design and execution service.',category:'Business',stage:'Trying',links:['quotation','hardware']},{id:'pricing',title:'Pricing packages',notes:'Simple renovation packages that make project scope and costs transparent.',category:'Business',stage:'Captured',links:['quotation']},{id:'website',title:'Website inspiration',notes:'A calm, minimal website with a useful project gallery and straightforward enquiry flow.',category:'Design',stage:'Captured',links:['interior']}].map((a,i)=>({...a,created:now-(i+1)*86400000,updated:now-i*86400000,source:'text',attachments:[],history:[],links:a.links||[],deleted:false,archived:false}));
let state={ideas:[],settings:{name:'Your space',review:true,quiet:true,language:'en-IN',time:'18:00',day:'Friday'}};let page='home',query='',filter='All',searchCategory='All',searchStage='All',selected=null,graphScale=1,recording=false,recognition=null,mediaRecorder=null,mediaStream=null,recordChunks=[],recordData=null,recordTranscript='',recordTimer=null,recordSeconds=0;
const persist=()=>queueServerSave();
const alive=()=>state.ideas.filter(i=>!i.deleted&&!i.archived);const get=id=>state.ideas.find(i=>i.id===id);const date=s=>new Date(s).toLocaleDateString('en-IN',{day:'numeric',month:'short'});const reminderText=s=>new Date(s).toLocaleString('en-IN',{day:'numeric',month:'short',hour:'numeric',minute:'2-digit'});const toast=m=>{let t=document.getElementById('toast');t.textContent=m;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),3200)};
function go(p){page=p;query='';filter='All';document.body.classList.remove('nav-open');render();window.scrollTo(0,0)}
function shell(body){let navs=[['home','Home'],['inbox','Inbox'],['search','Search'],['rediscover','Rediscover'],['graph','Graph'],['archive','Archive']];document.getElementById('app').innerHTML=`<aside><div class="brand">${icon('bulb')}Idea Space</div><button class="primary new" onclick="openCapture()">${icon('plus')}New idea</button><nav>${navs.map(([id,title])=>`<button class="nav ${page===id?'active':''}" onclick="go('${id}')">${icon(id)}${title}${id==='inbox'?`<span class="badge">${alive().filter(i=>i.stage==='Captured').length}</span>`:''}</button>`).join('')}</nav><div class="side-bottom"><button class="nav ${page==='settings'?'active':''}" onclick="go('settings')">${icon('settings')}Settings</button><button class="nav ${page==='trash'?'active':''}" onclick="go('trash')">${icon('trash')}Trash</button><div class="profile"><span class="avatar">${icon('bulb')}</span><div>${esc(state.settings.name||'Your space')}<small>A little room for big ideas</small></div></div></div></aside><main><header class="topbar"><button class="menu-btn" aria-label="Open navigation" onclick="document.body.classList.toggle('nav-open')">${icon('menu')}</button><form class="searchbar" onsubmit="event.preventDefault();startSearch(this.q.value)">${icon('search')}<input name="q" aria-label="Search all ideas" placeholder="Search ideas, notes, anything…"><span class="keyboard">⌘ K</span></form><div class="top-actions"><span class="storage-label"><span class="dot"></span><span data-sync>${esc(syncLabel)}</span></span><button class="notification" aria-label="View reminders" onclick="showReminders()">${icon('bell')}</button><button class="link" onclick="signOut()">Sign out</button></div></header>${body}<div class="hint">${icon('lock')} A private space for your thoughts. Saved to your account.</div></main>`}
function head(title,sub,extra=''){return `<div class="pagehead"><div><h1>${title}</h1><p>${sub}</p></div>${extra||`<span class="date">${new Date().toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long'})}</span>`}</div>`}
function ideaCard(i,small=false){return `<article class="card idea-card" tabindex="0" role="button" aria-label="Open ${esc(i.title)}" onclick="openIdea('${i.id}')" onkeydown="if(event.key==='Enter')openIdea('${i.id}')"><div class="cover">${i.cover?`<img src="${esc(i.cover)}" alt="" loading="lazy" onerror="this.style.display='none'">`:''}<span class="tag ${esc(i.category)}">${esc(i.category||'Unsorted')}</span><button class="dots" aria-label="Idea actions" onclick="event.stopPropagation();ideaActions('${i.id}')">•••</button></div><div class="idea-content"><h3>${esc(i.title)}</h3><p>${esc(i.notes.slice(0,100))}</p><div class="idea-foot"><span>${icon('calendar')}${date(i.created)}</span><button onclick="event.stopPropagation();openIdea('${i.id}')">Open idea ${icon('arrow')}</button></div></div></article>`}
function home(){let list=alive(),rev=list.filter(i=>i.reminder).sort((a,b)=>new Date(a.reminder)-new Date(b.reminder));return head('Make room for your next idea','Capture. Revisit. Connect. Turn your ideas into something real.')+`<div class="home-layout"><div><section class="card capture"><div class="capture-title">${icon('bulb')}What just came to mind?</div><textarea id="quick" aria-label="Your idea" placeholder="A thought, a possibility, a little spark…"></textarea><div class="capture-foot"><div class="modes"><button class="mode active" onclick="document.getElementById('quick').focus()">${icon('text')}<span>Text</span></button><button class="mode" onclick="openVoice()">${icon('voice')}<span>Voice</span></button><button class="mode" onclick="openCapture('photo')">${icon('photo')}<span>Photo</span></button><button class="mode" onclick="openCapture('link')">${icon('link')}<span>Link</span></button></div><button class="primary" onclick="quickSave()">Save idea ${icon('arrow')}</button></div></section><div class="section-head"><h2 class="label">${icon('calendar')}Revisit today</h2><button class="link" onclick="go('rediscover')">See all ${icon('arrow')}</button></div>${rev.length?`<div class="two">${rev.slice(0,2).map(i=>ideaCard(i)).join('')}</div>`:`<div class="card empty">${icon('calendar')}<p>Give an idea a moment to come back.</p><button class="link" onclick="go('inbox')">Choose an idea →</button></div>`}<div class="section-head"><h2 class="label">${icon('clock')}Recent ideas</h2><button class="link" onclick="go('inbox')">See all ${icon('arrow')}</button></div><div class="three">${list.sort((a,b)=>b.created-a.created).filter(i=>!rev.slice(0,2).includes(i)).slice(0,3).map(i=>ideaCard(i,true)).join('')}</div></div><div class="right-rail"><section class="card"><div class="rail-title">${icon('spark')}Your week</div>${[[list.filter(i=>now-i.created<7*86400000).length,'ideas captured','bulb'],[list.filter(i=>i.revisited&&Date.now()-i.revisited<7*86400000).length,'ideas revisited','rediscover'],[list.filter(i=>i.nextDone).length,'next steps completed','check']].map(([n,t,ic])=>`<div class="stats"><span class="bubble">${icon(ic)}</span><div><strong>${n}</strong><small>${t}</small></div></div>`).join('')}</section><section class="card review"><div class="rail-title">${icon('calendar')}Weekly review <button aria-label="Toggle weekly review" class="toggle ${state.settings.review?'on':''}" style="margin-left:auto" onclick="toggleSetting('review')"><span></span></button></div><p>${esc(state.settings.day)}, ${esc(state.settings.time)}<br>A gentle moment to reflect on your ideas and find a next step.</p><button class="link" onclick="go('rediscover')">Review your ideas ${icon('arrow')}</button></section><div class="review-quote">“Every great thing starts<br>with a small idea.”</div></div></div>`}
function listRow(i,trash=false){return `<div class="list-row" ${trash?'':`tabindex="0" role="button" aria-label="Open ${esc(i.title)}" onkeydown="if(event.key==='Enter')openIdea('${i.id}')"`} onclick="${trash?'':`openIdea('${i.id}')`}"><span class="source-icon">${icon(i.source==='photo'?'photo':i.source==='voice'?'voice':i.source==='link'?'link':'text')}</span><div class="list-content"><h3>${esc(i.title)}</h3><p>${esc(i.notes||'No notes yet. Let this idea grow.')}</p><div class="row-meta"><span class="tag ${esc(i.category)}">${esc(i.category||'Unsorted')}</span><span class="sub">${esc(i.stage)} · ${date(i.created)}</span></div></div>${trash?`<button class="secondary" onclick="restore('${i.id}')">Restore</button><button class="danger" aria-label="Delete permanently" onclick="permanentDelete('${i.id}')">${icon('trash')}</button>`:`<button aria-label="Idea actions" onclick="event.stopPropagation();ideaActions('${i.id}')">•••</button>`}</div>`}
function inbox(arch=false){let list=state.ideas.filter(i=>!i.deleted&&(arch?i.archived:!i.archived)).filter(i=>filter==='All'||i.source===filter.toLowerCase()).filter(i=>(i.title+' '+i.notes).toLowerCase().includes(query.toLowerCase()));return head(arch?'A place to set ideas aside':'Your idea inbox',arch?'Ideas can rest here until you need them again.':'Capture first. Organize when you are ready.',`<button class="primary" onclick="openCapture()">${icon('plus')}New idea</button>`)+`<div class="toolbar">${['All','Text','Voice','Photo','Link'].map(f=>`<button class="pill ${filter===f?'selected':''}" onclick="filter='${f}';render()">${f}</button>`).join('')}<input style="margin-left:auto;max-width:230px;font-size:11px" aria-label="Filter ideas" placeholder="Filter ideas…" value="${esc(query)}" oninput="query=this.value;updateList()"></div><section class="card" style="padding:0" id="idea-list">${list.length?list.sort((a,b)=>b.created-a.created).map(i=>listRow(i)).join(''):empty('No ideas here yet.','Save a thought whenever inspiration arrives.')}</section>`}
function updateList(){let list=state.ideas.filter(i=>!i.deleted&&(page==='archive'?i.archived:!i.archived)).filter(i=>filter==='All'||i.source===filter.toLowerCase()).filter(i=>(i.title+' '+i.notes).toLowerCase().includes(query.toLowerCase()));document.getElementById('idea-list').innerHTML=list.length?list.map(i=>listRow(i)).join(''):empty('No matching ideas.','Try another word.')}function empty(t,s){return `<div class="empty">${icon('bulb')}<h3>${t}</h3><p class="sub">${s}</p></div>`}
function startSearch(q){page='search';query=q;render()}
function search(){return head('Find your next thought','Search across ideas, notes, transcripts and attachment names.')+`<div class="toolbar"><input id="search-input" style="flex:1;min-width:180px" aria-label="Search ideas" placeholder="What are you looking for?" value="${esc(query)}" oninput="query=this.value;searchResults()"><select aria-label="Category filter" onchange="searchCategory=this.value;searchResults()"><option>All</option>${['Business','Design','Personal','Unsorted'].map(c=>`<option ${searchCategory===c?'selected':''}>${c}</option>`).join('')}</select><select aria-label="Stage filter" onchange="searchStage=this.value;searchResults()"><option>All</option>${['Captured','Exploring','Trying','Completed'].map(c=>`<option ${searchStage===c?'selected':''}>${c}</option>`).join('')}</select></div><div id="search-results"></div>`}
function searchResults(){let list=alive().filter(i=>(i.title+' '+i.notes+' '+(i.tags||'')+' '+i.attachments.map(a=>a.name).join(' ')).toLowerCase().includes(query.toLowerCase())&&(searchCategory==='All'||i.category===searchCategory)&&(searchStage==='All'||i.stage===searchStage));let el=document.getElementById('search-results');if(el)el.innerHTML=`<p class="sub" style="margin-bottom:16px">${list.length} ${list.length===1?'idea':'ideas'} found</p><div class="card" style="padding:0">${list.length?list.map(i=>listRow(i)).join(''):empty('Nothing found just yet.','Try a different word or clear your filters.')}</div>`}
function detail(){let i=get(selected);if(!i)return empty('Idea not found','Choose another idea.');return `<div class="breadcrumb"><button onclick="go('inbox')">Inbox</button> / ${esc(i.title)}</div><form id="detail-form" onsubmit="event.preventDefault();saveDetail()"><div class="pagehead" style="margin-top:0"><div style="flex:1"><input class="detail-title" name="title" value="${esc(i.title)}" aria-label="Idea title" required><span class="tag ${esc(i.category)}">${esc(i.category||'Unsorted')}</span></div><button type="button" aria-label="Favorite idea" style="color:${i.favorite?'#d7ae5a':'#b4a3c2'}" onclick="toggleFavorite('${i.id}')">${icon('star')}</button><button class="primary" type="submit">Save changes</button></div><div class="detail-layout"><div class="stack"><section class="card"><div class="editor-tools"><span>Notes</span><span style="margin-left:auto">Your words, your way</span>${icon('text')}</div><textarea class="notearea" name="notes" aria-label="Idea notes" placeholder="Let your idea grow…">${esc(i.notes)}</textarea></section><div class="two contexts"><section class="card"><label>Why this matters (optional)</label><textarea name="why" style="min-height:85px" placeholder="What makes this worth remembering?">${esc(i.why||'')}</textarea></section><section class="card"><label>What triggered this idea? (optional)</label><textarea name="trigger" style="min-height:85px" placeholder="A conversation, a problem, a moment…">${esc(i.trigger||'')}</textarea></section></div><section class="card"><div class="rail-title">${icon('photo')}Attachments <button type="button" class="link" style="margin-left:auto" onclick="document.getElementById('attach').click()">+ Add attachment</button></div><input hidden type="file" id="attach" onchange="attachToIdea(this.files[0])">${i.attachments.map(a=>`<div class="file-item">${a.type.startsWith('image/')?`<img src="${a.data}" alt="${esc(a.name)}">`:icon('text')}<a href="${a.data}" download="${esc(a.name)}">${esc(a.name)}</a><button type="button" aria-label="Remove attachment" style="margin-left:auto" onclick="removeAttachment('${a.id}')">${icon('close')}</button></div>`).join('')}${!i.attachments.length?'<p class="sub">Keep photos, links and references close to your idea.</p>':''}${i.audio?`<audio controls src="${i.audio}" style="width:100%;margin-top:15px"></audio>`:''}</section><section class="card"><div class="rail-title">${icon('clock')}Idea history <button type="button" class="link" style="margin-left:auto" onclick="addUpdate('${i.id}')">+ Add update</button></div><div style="margin-top:18px">${[...(i.history||[])].reverse().slice(0,5).map(h=>`<div class="history-item"><small>${date(h.at)}</small>${esc(h.text)}</div>`).join('')}<div class="history-item"><small>${date(i.created)}</small>First spark captured.</div></div></section></div><div class="stack"><section class="card"><div class="field"><label>Category</label><select name="category">${['Unsorted','Business','Design','Personal'].map(c=>`<option ${i.category===c?'selected':''}>${c}</option>`).join('')}</select></div><label>Stage</label><select name="stage">${['Captured','Exploring','Trying','Completed'].map(c=>`<option ${i.stage===c?'selected':''}>${c}</option>`).join('')}</select><label style="margin-top:18px">Tags</label><input name="tags" value="${esc(i.tags||'')}" placeholder="e.g. product, renovation"></section><section class="card"><h3>One next step</h3><label class="check"><input type="checkbox" name="nextDone" ${i.nextDone?'checked':''}>Mark as complete</label><input name="next" value="${esc(i.next||'')}" placeholder="Start small…" style="font-size:12px"></section><section class="card"><div class="rail-title">${icon('calendar')}Bring it back</div><p class="sub">${i.reminder?reminderText(i.reminder):'Give this idea a moment to return.'}</p><button type="button" class="secondary" onclick="saveDetail(false);openReminder('${i.id}')">${i.reminder?'Change reminder':'Set a reminder'}</button></section><section class="card"><h3>Related ideas</h3>${i.links.filter(id=>get(id)&&!get(id).deleted).map(id=>`<button type="button" class="file-item" style="width:100%;text-align:left" onclick="saveDetail(false);openIdea('${id}')">${icon('link')}${esc(get(id).title)}</button>`).join('')}<button type="button" class="small-btn" onclick="saveDetail(false);connectIdea('${i.id}')">+ Connect an idea</button></section></div></div></form>`}
function openIdea(id){selected=id;get(id).revisited=Date.now();persist();page='detail';closeModal();render();window.scrollTo(0,0)}
function saveDetail(notify=true){let f=document.getElementById('detail-form');if(!f)return;let data=new FormData(f),i=get(selected);if(!String(data.get('title')).trim())return toast('Give your idea a title.');for(let k of ['title','notes','why','trigger','category','stage','tags','next'])i[k]=String(data.get(k)||'').trim();i.nextDone=data.has('nextDone');i.updated=Date.now();if(persist()&&notify)toast('Changes queued for saving.')}function toggleFavorite(id){get(id).favorite=!get(id).favorite;persist();saveDetail(false);render()}
function quickSave(){let text=document.getElementById('quick').value.trim();if(!text)return toast('Write a little thought first.');let saved=createIdea({title:text.split('\n')[0].slice(0,95),notes:text.includes('\n')?text:''});if(!saved)return;toast('Idea captured. Saving to your account…');render()}
function createIdea(data){let i={id:uid(),title:'Untitled idea',notes:'',category:'Unsorted',stage:'Captured',created:Date.now(),updated:Date.now(),source:'text',links:[],attachments:[],history:[],deleted:false,archived:false,...data};state.ideas.unshift(i);if(!persist()){state.ideas.shift();return null}return i}
function modal(html,wide=false){document.getElementById('overlay').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true">${html}</section></div>`;setTimeout(()=>document.querySelector('.modal input,.modal textarea,.modal button')?.focus(),20)}
function modalHead(t){return `<div class="modal-head"><h2>${t}</h2><button class="close" aria-label="Close dialog" onclick="closeModal()">${icon('close')}</button></div>`}function closeModal(){if(recording)stopVoice();document.getElementById('overlay').innerHTML=''}
function openCapture(mode='text'){modal(`${modalHead('Catch a little spark')}<form onsubmit="event.preventDefault();saveCapture(this)"><div class="field"><label>Idea title</label><input name="title" placeholder="What just came to mind?" required maxlength="180"></div><div class="field"><label>${mode==='link'?'Link':'Notes (optional)'}</label>${mode==='link'?'<input type="url" name="url" placeholder="https://…" required>':'<textarea name="notes" placeholder="A few words now can help you remember later…"></textarea>'}</div>${mode==='photo'?'<div class="field"><label>Add a photo</label><input type="file" name="photo" accept="image/*" required></div>':''}<div class="two"><div><label>Category</label><select name="category"><option>Unsorted</option><option>Business</option><option>Design</option><option>Personal</option></select></div><div><label>Stage</label><select name="stage"><option>Captured</option><option>Exploring</option><option>Trying</option></select></div></div><div class="modal-actions"><button type="button" class="secondary" onclick="closeModal()">Cancel</button><button class="primary" type="submit">Save idea ${icon('arrow')}</button></div><input hidden name="source" value="${mode}"></form>`)}
async function saveCapture(f){let d=new FormData(f);if(!String(d.get('title')).trim())return toast('Give your idea a title.');let attachments=[],file=d.get('photo');if(file&&file.size){let a=await fileData(file);if(!a)return;attachments.push(a)}let item=createIdea({title:String(d.get('title')).trim(),notes:String(d.get('notes')||d.get('url')||''),category:d.get('category'),stage:d.get('stage'),source:d.get('source'),attachments,cover:attachments.find(a=>a.type.startsWith('image/'))?.data});if(item){closeModal();render();toast('Idea captured. You can organize it later.')}}
function fileData(file){if(file.size>2000000){toast('Choose a file smaller than 2 MB for this release.');return Promise.resolve(null)}return new Promise(resolve=>{let r=new FileReader;r.onload=()=>resolve({id:uid(),name:file.name,type:file.type||'application/octet-stream',data:r.result});r.readAsDataURL(file)})}async function attachToIdea(file){if(!file)return;saveDetail(false);let a=await fileData(file);if(a){get(selected).attachments.push(a);if(persist())render();else get(selected).attachments.pop()}}function removeAttachment(id){saveDetail(false);get(selected).attachments=get(selected).attachments.filter(a=>a.id!==id);persist();render()}
function addUpdate(id){modal(`${modalHead('A new thought')}<form onsubmit="event.preventDefault();get('${id}').history.push({at:Date.now(),text:this.update.value});persist();closeModal();render();toast('Update added to your idea history.')"><textarea name="update" placeholder="How has this idea grown?" required></textarea><div class="modal-actions"><button class="primary">Add update</button></div></form>`)}
function ideaActions(id){let i=get(id);modal(`${modalHead(esc(i.title))}<div class="stack"><button class="secondary" onclick="openIdea('${id}')">${icon('text')}Open idea</button><button class="secondary" onclick="openReminder('${id}')">${icon('calendar')}Set reminder</button><button class="secondary" onclick="get('${id}').archived=!get('${id}').archived;persist();closeModal();render();toast('Idea updated.')">${icon('archive')}${i.archived?'Unarchive':'Archive'} idea</button><button class="secondary danger" onclick="get('${id}').deleted=true;get('${id}').deletedAt=Date.now();persist();closeModal();if(page==='detail')page='inbox';render();toast('Moved to Trash. You can restore it later.')">${icon('trash')}Move to Trash</button></div>`)}
function openReminder(id){let i=get(id),v=i.reminder?new Date(new Date(i.reminder).getTime()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16):new Date(Date.now()+86400000-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16);modal(`${modalHead('Bring this idea back')}<p class="sub">${esc(i.title)}</p><form onsubmit="event.preventDefault();saveReminder('${id}',this)"><div class="toolbar" style="margin-top:20px">${[['Tomorrow',1],['This weekend',((6-new Date().getDay()+7)%7)||7],['Next week',7]].map(([s,d])=>`<button type="button" class="pill" onclick="document.getElementById('rem-date').value=new Date(Date.now()+${d}*86400000-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16)">${s}</button>`).join('')}</div><div class="field"><label>Date and time (your local timezone)</label><input id="rem-date" type="datetime-local" name="when" value="${v}" required></div><div class="field"><label>Repeat</label><select name="repeat"><option value="none">Does not repeat</option><option value="daily">Daily</option><option value="weekly">Weekly</option><option value="monthly">Monthly</option></select></div><div class="field"><label>When would this be useful? (optional)</label><textarea name="context" style="min-height:80px" placeholder="Before planning the first prototype…">${esc(i.context||'')}</textarea></div><p class="sub">In-app reminders appear while Idea Space is open. Email delivery and background notifications are not connected.</p><div class="modal-actions">${i.reminder?`<button type="button" class="secondary" onclick="delete get('${id}').reminder;persist();closeModal();render()">Remove reminder</button>`:''}<button class="primary">Save reminder</button></div></form>`)}
function saveReminder(id,f){let when=new Date(f.when.value);if(when<=new Date())return toast('Choose a time in the future.');let i=get(id);i.reminder=when.toISOString();i.repeat=f.repeat.value;i.context=f.context.value;i.notified=false;persist();closeModal();render();toast('Reminder set for '+reminderText(i.reminder))}
function showReminders(){let list=alive().filter(i=>i.reminder).sort((a,b)=>new Date(a.reminder)-new Date(b.reminder));modal(`${modalHead('A moment to revisit')}<div>${list.length?list.map(i=>`<div class="list-row" onclick="openIdea('${i.id}')"><span class="source-icon">${icon('calendar')}</span><div class="list-content"><h3>${esc(i.title)}</h3><p>${reminderText(i.reminder)}</p></div><button class="link" onclick="event.stopPropagation();snooze('${i.id}')">Snooze</button></div>`).join(''):empty('No reminders yet.','Set a reminder from any idea.')}</div>`)}
function snooze(id){let i=get(id);i.reminder=new Date(Date.now()+86400000).toISOString();i.notified=false;persist();closeModal();render();toast('Snoozed until tomorrow.')}
function rediscover(){let list=alive().filter(i=>!i.reminder||new Date(i.reminder)<=new Date()).sort((a,b)=>(a.revisited||a.updated)-(b.revisited||b.updated));if(!list.length)list=alive();return head('Good ideas deserve a second look','Rediscover past ideas, find fresh connections, and move one thought forward.')+`<div class="toolbar"><span class="sub">A few ideas from your shelf</span><button class="pill" style="margin-left:auto" onclick="go('settings')">${icon('calendar')}Weekly review ${esc(state.settings.day)}, ${esc(state.settings.time)}</button></div><div class="two">${list.slice(0,2).map(i=>`<section class="card"><span class="tag ${i.category}">${esc(i.category)}</span><h2 style="margin:17px 0 10px">${esc(i.title)}</h2><p class="sub" style="min-height:50px">${esc(i.notes.slice(0,170))}</p>${i.audio?`<audio src="${i.audio}" controls style="width:100%"></audio>`:''}<div class="toolbar" style="margin:20px 0 0"><button class="primary" onclick="openIdea('${i.id}')">${icon('rediscover')}Revisit</button><button class="secondary" onclick="snooze('${i.id}')">Snooze</button><button class="secondary" onclick="get('${i.id}').archived=true;persist();render();toast('Idea archived.')">Archive</button></div></section>`).join('')}</div><div class="section-head"><h2>Move an idea forward</h2><span class="sub">Small steps count.</span></div><div class="board">${['Captured','Exploring','Trying','Completed'].map(s=>`<section class="column"><h3>${s}<span>${alive().filter(i=>i.stage===s).length}</span></h3>${alive().filter(i=>i.stage===s).map(i=>`<div class="board-card"><button style="padding:0;text-align:left;font-weight:600" onclick="openIdea('${i.id}')">${esc(i.title)}</button><p class="sub" style="font-size:10px">${esc(i.category)}</p><select aria-label="Change stage for ${esc(i.title)}" onchange="get('${i.id}').stage=this.value;persist();render()">${['Captured','Exploring','Trying','Completed'].map(c=>`<option ${c===s?'selected':''}>${c}</option>`).join('')}</select></div>`).join('')}</section>`).join('')}</div>`}
function connectIdea(id){let i=get(id),options=alive().filter(a=>a.id!==id&&!i.links.includes(a.id));modal(`${modalHead('Connect your thoughts')}<p class="sub">Link “${esc(i.title)}” to another idea.</p><form onsubmit="event.preventDefault();let a=get('${id}'),b=get(this.target.value);if(!b)return;a.links.push(b.id);if(!b.links.includes(a.id))b.links.push(a.id);persist();closeModal();render();toast('Ideas connected.')"><label style="margin-top:20px">Related idea</label><select name="target" required>${options.map(a=>`<option value="${a.id}">${esc(a.title)}</option>`).join('')}</select><div class="modal-actions"><button class="primary" ${!options.length?'disabled':''}>Connect ideas</button></div></form>`)}
function graph(){return head('Your ideas, connected','A little space to see how your thoughts fit together.',`<button class="secondary" onclick="graphScale=1;render()">${icon('graph')}Reset view</button>`)+`<div class="graph-shell"><svg class="graph-svg" id="graph" viewBox="0 0 1000 650" aria-label="Connected ideas graph"></svg><div class="graph-legend"><span style="--c:#a07bdc">Business</span><span style="--c:#6bbfb7">Design</span><span style="--c:#e6b96c">Personal</span></div><div class="graph-controls"><button aria-label="Zoom out" onclick="zoomGraph(-.15)">−</button><span id="zoom-label">100%</span><button aria-label="Zoom in" onclick="zoomGraph(.15)">+</button><span style="color:#b8abc7;padding:0 8px">Drag a node · Click to open</span></div></div>`}
function drawGraph(){let svg=document.getElementById('graph');if(!svg)return;let list=alive(),colors={Business:'#a783dc',Design:'#68bcb5',Personal:'#e5b46b',Unsorted:'#9ea6c7'},nodes=[],groups=['Business','Design','Personal','Unsorted'].filter(c=>list.some(i=>i.category===c));nodes.push({id:'root',x:500,y:310,label:'Ideas',color:'#9462e7',r:29,root:true});const center={Business:[270,210],Design:[750,190],Personal:[700,450],Unsorted:[240,480]};for(let c of groups){let [x,y]=center[c];nodes.push({id:c,x,y,label:c,color:colors[c],r:19,group:true});let a=list.filter(i=>i.category===c);a.forEach((i,j)=>{let angle=(j/Math.max(a.length,3))*Math.PI*2-1.9;let slots={Business:[[130,80],[340,75],[420,220],[110,300],[290,365]],Design:[[835,80],[900,245],[650,70]],Personal:[[620,565],[870,510],[865,385]],Unsorted:[[110,560],[365,560],[100,440]]};let point=slots[c][j];nodes.push({id:i.id,x:point?point[0]:x+Math.cos(angle)*165,y:point?point[1]:y+Math.sin(angle)*150,label:i.title,color:colors[c],r:8,idea:i})})}let pos=Object.fromEntries(nodes.map(n=>[n.id,n]));const edges=[];groups.forEach(c=>edges.push(['root',c]));list.forEach(i=>{edges.push([i.category,i.id]);i.links.forEach(id=>{if(pos[id]&&i.id<id)edges.push([i.id,id])})});function paint(){svg.innerHTML=`<g id="graph-stage" transform="translate(${500*(1-graphScale)} ${325*(1-graphScale)}) scale(${graphScale})">${edges.filter(e=>pos[e[0]]&&pos[e[1]]).map(([a,b])=>`<line x1="${pos[a].x}" y1="${pos[a].y}" x2="${pos[b].x}" y2="${pos[b].y}" stroke="#e7e3ef" stroke-width="${a==='root'?1.2:.8}"/>`).join('')}${nodes.map(n=>`<g class="graph-node" data-id="${esc(n.id)}" transform="translate(${n.x} ${n.y})" tabindex="0" role="button" aria-label="${esc(n.label)}"><circle r="${n.r+6}" fill="${n.color}" opacity=".06"/><circle r="${n.r}" fill="${n.color}" opacity="${n.idea?'.85':'.95'}"/>${n.root?'<path d="M-5 2c0-3-4-3-4-8a9 9 0 0118 0c0 5-4 5-4 8v3H-5V2m1 7h8" fill="none" stroke="white" stroke-width="1.6"/>':''}<text y="${n.r+21}" text-anchor="middle" fill="${n.group||n.root?'#625071':'#9a8ba6'}" font-size="${n.root?'15':n.group?'12':'10'}" font-weight="${n.group||n.root?'600':'400'}">${esc(n.label.length>27?n.label.slice(0,25)+'…':n.label)}</text></g>`).join('')}</g>`;document.getElementById('zoom-label').textContent=Math.round(graphScale*100)+'%'}paint();let drag=null,moved=false;svg.onpointerdown=e=>{let g=e.target.closest('.graph-node');if(!g)return;drag=pos[g.dataset.id];moved=false;svg.setPointerCapture(e.pointerId)};svg.onpointermove=e=>{if(!drag)return;let p=new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse());drag.x=(p.x-500*(1-graphScale))/graphScale;drag.y=(p.y-325*(1-graphScale))/graphScale;moved=true;paint()};svg.onpointerup=()=>{if(drag&&!moved&&drag.idea)openIdea(drag.id);drag=null};svg.onkeydown=e=>{if(e.key==='Enter'){let n=e.target.closest('.graph-node');if(n&&get(n.dataset.id))openIdea(n.dataset.id)}}}
function zoomGraph(n){graphScale=Math.max(.5,Math.min(2,graphScale+n));drawGraph()}
function settings(){let s=state.settings;return head('A space that feels like you','Choose how you capture, revisit and keep your ideas.')+`<div class="settings-grid"><section class="card"><h2>Preferences & reminders</h2><div class="setting-row"><div><h3>Space name</h3><p>Make this little corner yours.</p></div><input style="width:160px" aria-label="Space name" value="${esc(s.name)}" onchange="state.settings.name=this.value;persist();render()"></div>${settingToggle('review','Weekly idea review','A gentle reminder while the app is open.') }<div class="setting-row"><label>Review schedule</label><div><select aria-label="Review day" onchange="state.settings.day=this.value;persist()">${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].map(d=>`<option ${s.day===d?'selected':''}>${d}</option>`).join('')}</select><input type="time" aria-label="Review time" value="${esc(s.time)}" style="margin-top:8px" onchange="state.settings.time=this.value;persist()"></div></div>${settingToggle('quiet','Quiet hours','No in-app prompts between 10 PM and 8 AM.')}<div class="setting-row"><div><h3>Voice language</h3><p>Use the language you think in.</p></div><select aria-label="Voice language" onchange="state.settings.language=this.value;persist()"><option value="en-IN" ${s.language==='en-IN'?'selected':''}>English (India)</option><option value="hi-IN" ${s.language==='hi-IN'?'selected':''}>Hindi</option></select></div></section><div class="stack"><section class="card"><h2>Your data, your ideas</h2><div class="setting-row"><div><h3>Private by default</h3><p>Ideas are stored in MySQL and accessible only through your signed-in account.</p></div>${icon('lock')}</div><div class="setting-row"><div><h3>Export a backup</h3><p>Download all ideas and attachments.</p></div><button class="secondary" onclick="exportData()">${icon('download')}JSON</button></div><div class="setting-row"><div><h3>Export your notes</h3><p>A readable Markdown file.</p></div><button class="secondary" onclick="exportMarkdown()">${icon('download')}Notes</button></div><div class="setting-row"><div><h3>Restore a backup</h3><p>Import an Idea Space JSON backup.</p></div><button class="secondary" onclick="document.getElementById('import-file').click()">Import</button><input type="file" hidden id="import-file" accept="application/json" onchange="importData(this.files[0])"></div></section><section class="card review"><h3>Your account is connected</h3><p>Sign in on another device to access your saved ideas. Export a backup for an extra copy. Use Refresh to load changes made on another device.</p><button class="secondary" onclick="refreshAccount()">Refresh account data</button></section></div></div>`}
function settingToggle(k,t,sub){return `<div class="setting-row"><div><h3>${t}</h3><p>${sub}</p></div><button class="toggle ${state.settings[k]?'on':''}" role="switch" aria-checked="${!!state.settings[k]}" aria-label="${t}" onclick="toggleSetting('${k}')"><span></span></button></div>`}function toggleSetting(k){state.settings[k]=!state.settings[k];persist();render()}
function downloadFile(name,text,type){let url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}function exportData(){downloadFile('idea-space-backup.json',JSON.stringify(state,null,2),'application/json');toast('Backup downloaded.')}function exportMarkdown(){downloadFile('idea-space-notes.md',alive().map(i=>`# ${i.title}\n\n${i.category} · ${i.stage}\n\n${i.notes}\n\n${i.why?'## Why this matters\n'+i.why:''}\n\n---\n`).join('\n'),'text/markdown')}
async function importData(file){if(!file)return;try{let d=JSON.parse(await file.text());validateImport(d);modal(`${modalHead('Restore your backup?')}<p class="sub">This will replace the ideas currently in your account with ${d.ideas.length} ideas from your backup. Export your current ideas first if you want to keep them.</p><div class="modal-actions"><button class="secondary" onclick="closeModal()">Cancel</button><button id="confirm-import" class="primary">Restore backup</button></div>`);document.getElementById('confirm-import').onclick=()=>{let old=state;state={ideas:d.ideas.map(i=>({...i,attachments:i.attachments||[],history:i.history||[],links:i.links||[]})),settings:{...old.settings,...d.settings}};if(persist()){closeModal();render();toast('Backup restored.')}else state=old}}catch{toast('That file is not a valid Idea Space backup.')}}
function trash(){let list=state.ideas.filter(i=>i.deleted);return head('Recently deleted ideas','Some thoughts deserve another chance.')+`<div class="reminder-banner" style="margin:0 0 22px">${icon('trash')}Deleted ideas stay here until you permanently remove them.</div><section class="card" style="padding:0">${list.length?list.map(i=>listRow(i,true)).join(''):empty('Nothing in the trash.','Deleted ideas will appear here, ready to restore.')}</section>`}function restore(id){get(id).deleted=false;get(id).archived=false;persist();render();toast('Idea restored to your inbox.')}function permanentDelete(id){modal(`${modalHead('Let this idea go?')}<p class="sub">“${esc(get(id).title)}” and its attachments will be permanently deleted from your account. This cannot be undone.</p><div class="modal-actions"><button class="secondary" onclick="closeModal()">Keep it</button><button class="primary" style="background:#bc6679;border-color:#bc6679" onclick="state.ideas=state.ideas.filter(i=>i.id!=='${id}');persist();closeModal();render();toast('Idea permanently deleted.')">Delete permanently</button></div>`)}
function openVoice(){recordData=null;recordTranscript='';recordSeconds=0;modal(`${modalHead('Capture an idea by voice')}<div class="record-panel"><div class="record-circle" id="record-circle">${icon('voice')}</div><h3 id="record-status">A thought worth saying out loud.</h3><div class="timer" id="timer">00:00</div><button class="primary" id="record-btn" onclick="startVoice()">${icon('voice')}Start recording</button></div><label>Idea title</label><input id="voice-title" placeholder="Give your thought a name…"><label style="margin-top:18px">Transcript / notes</label><textarea id="voice-transcript" placeholder="Your transcript appears here when supported. You can also type or edit your notes."></textarea><p class="sub" id="voice-help">Microphone permission is required. Transcription availability depends on your browser. Audio is saved with your idea.</p><div class="modal-actions"><button class="secondary" onclick="closeModal()">Cancel</button><button class="primary" onclick="saveVoice()">Save idea</button></div>`)}
async function startVoice(){if(recording){stopVoice();return}if(!navigator.mediaDevices?.getUserMedia){toast('Recording is not supported here. You can still type your idea.');return}try{mediaStream=await navigator.mediaDevices.getUserMedia({audio:true});recordChunks=[];mediaRecorder=new MediaRecorder(mediaStream);mediaRecorder.ondataavailable=e=>{if(e.data.size)recordChunks.push(e.data)};mediaRecorder.onstop=()=>{const blob=new Blob(recordChunks,{type:mediaRecorder.mimeType||'audio/webm'});const reader=new FileReader();reader.onload=()=>{recordData=reader.result;toast('Recording ready. Add a title and save.');};reader.readAsDataURL(blob);mediaStream?.getTracks().forEach(t=>t.stop())};mediaRecorder.start();recording=true;document.getElementById('record-circle').classList.add('recording');document.getElementById('record-status').textContent='Recording your thought…';document.getElementById('record-btn').innerHTML=icon('stop')+'Stop recording';recordTimer=setInterval(()=>{recordSeconds++;let el=document.getElementById('timer');if(el)el.textContent=String(Math.floor(recordSeconds/60)).padStart(2,'0')+':'+String(recordSeconds%60).padStart(2,'0');if(recordSeconds>=60)stopVoice()},1000);const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(Speech){recognition=new Speech();recognition.lang=state.settings.language||'en-IN';recognition.continuous=true;recognition.interimResults=true;recognition.onresult=e=>{let text=Array.from(e.results).map(r=>r[0].transcript).join(' ');let el=document.getElementById('voice-transcript');if(el)el.value=text};recognition.onerror=()=>{let el=document.getElementById('voice-help');if(el)el.textContent='Audio is recording. Live transcription is unavailable; add notes after stopping.'};try{recognition.start()}catch{}}else document.getElementById('voice-help').textContent='Audio is recording. Live transcription is not supported in this browser; add notes after stopping.'}catch(e){toast('Microphone access was unavailable. You can type your idea instead.')}}
function stopVoice(){recording=false;clearInterval(recordTimer);recognition?.stop();if(mediaRecorder?.state==='recording')mediaRecorder.stop();let b=document.getElementById('record-btn');if(b){b.disabled=true;b.innerHTML=icon('check')+'Recording complete';document.getElementById('record-status').textContent='A thought, captured.';document.getElementById('record-circle').classList.remove('recording')}}function saveVoice(){if(recording){stopVoice();toast('Recording is finishing. Press Save idea again in a moment.');return}let title=document.getElementById('voice-title').value.trim(),notes=document.getElementById('voice-transcript').value.trim();if(!title)return toast('Give your voice idea a title.');if(!recordData&&!notes)return toast('Record a thought or add some notes first.');let i=createIdea({title,notes,source:'voice',audio:recordData});if(i){closeModal();render();toast('Your voice idea is saved.')}}
function render(){let content=page==='home'?home():page==='inbox'?inbox():page==='archive'?inbox(true):page==='search'?search():page==='detail'?detail():page==='rediscover'?rediscover():page==='graph'?graph():page==='settings'?settings():trash();shell(content);if(page==='search')searchResults();if(page==='graph')drawGraph()}
document.addEventListener('keydown',e=>{if(e.key==='Tab'&&document.querySelector('.modal')){let els=Array.from(document.querySelectorAll('.modal button:not([disabled]),.modal input:not([hidden]),.modal textarea,.modal select,.modal a')).filter(el=>el.offsetParent!==null);let first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}if(e.key==='Escape'){closeModal();document.body.classList.remove('nav-open')}if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();go('search');document.getElementById('search-input')?.focus()}});
setInterval(()=>{if(!account)return;let hour=new Date().getHours();if(state.settings.quiet&&(hour>=22||hour<8))return;let due=alive().filter(i=>i.reminder&&new Date(i.reminder)<=new Date()&&!i.notified);if(due.length){let i=due[0];i.notified=true;toast('Time to revisit: '+i.title);if(i.repeat&&i.repeat!=='none'){let d=new Date(i.reminder);if(i.repeat==='monthly')d.setMonth(d.getMonth()+1);else d.setDate(d.getDate()+(i.repeat==='daily'?1:7));i.reminder=d.toISOString();i.notified=false}persist()}let day=new Date().toLocaleDateString('en-US',{weekday:'long'}),time=new Date().toTimeString().slice(0,5),key=new Date().toDateString();if(state.settings.review&&day===state.settings.day&&time===state.settings.time&&state.settings.lastReview!==key){state.settings.lastReview=key;persist();toast('Your weekly idea review is ready. Visit Rediscover.')}},30000);
bootstrapServer();
